package com.slopus.happy.icons

import com.slopus.happy.layout.IconLayout
import com.slopus.happy.layout.IconMetrics
import com.slopus.happy.layout.PathElement
import com.slopus.happy.layout.Point
import com.slopus.happy.layout.VectorPath
import java.util.Base64

// Ported from happy-ios HappyIcons (Icon.swift, GlyphOutline.swift). The
// outlines are happy-app's icon-font glyphs, generated by happy-ios's
// scripts/generate-icons.py and copied as glyphs.txt by
// tools/icons/extract-ios-tables.py, so both apps draw the same shapes. No
// icon font is shipped.

/** An icon font happy-app draws through `@expo/vector-icons`. */
enum class IconFamily(val rawValue: String) {
    Ionicons("ionicons"),
    Octicons("octicons"),
    MaterialCommunityIcons("materialCommunityIcons"),
    MaterialIcons("materialIcons"),
    Feather("feather"),
    FontAwesome("fontAwesome"),
    FontAwesome5("fontAwesome5"),
}

/** One of happy-app's icons, named exactly as the RN code names it. */
data class Icon(val family: IconFamily, val name: String) {
    companion object {
        fun ionicons(name: String) = Icon(IconFamily.Ionicons, name)
        fun octicons(name: String) = Icon(IconFamily.Octicons, name)
        fun materialCommunityIcons(name: String) = Icon(IconFamily.MaterialCommunityIcons, name)
        fun materialIcons(name: String) = Icon(IconFamily.MaterialIcons, name)
        fun feather(name: String) = Icon(IconFamily.Feather, name)
        fun fontAwesome(name: String) = Icon(IconFamily.FontAwesome, name)
        fun fontAwesome5(name: String) = Icon(IconFamily.FontAwesome5, name)
    }
}

/**
 * A glyph's outline (font units, y down, origin on the ascender line at the
 * pen) and the font metrics needed to place it as RN's `<Text>` places it.
 */
data class IconGlyph(
    val path: VectorPath,
    val unitsPerEm: Double,
    val advance: Double,
    val ascender: Double,
    val descender: Double,
) {
    val metrics get() = IconMetrics(unitsPerEm, advance, ascender, descender)

    /** Where RN draws this glyph at [size] dp on a screen of [scale] pixels per dp. */
    fun layout(size: Double, scale: Double) = IconLayout(metrics, size, scale)
}

/** Every icon the app ships, from glyphs.txt. */
object IconCatalog {
    private class Font(val family: IconFamily, val unitsPerEm: Int, val ascender: Int, val descender: Int)
    private class Entry(val font: Font, val advance: Double, val outline: String)

    var sourceVersion: String = ""
        private set

    private val index: Map<Icon, Entry> by lazy {
        val map = HashMap<Icon, Entry>()
        var font: Font? = null
        val stream = IconCatalog::class.java.getResourceAsStream("/com/slopus/happy/icons/glyphs.txt")!!
        stream.bufferedReader().forEachLine { line ->
            when {
                line.startsWith("# version ") -> sourceVersion = line.removePrefix("# version ")
                line.startsWith("#") || line.isBlank() -> Unit
                line.startsWith("@font ") -> {
                    val f = line.split(' ')
                    font = Font(IconFamily.entries.first { it.rawValue == f[1] }, f[2].toInt(), f[3].toInt(), f[4].toInt())
                }
                else -> {
                    val fields = line.split(' ')
                    val current = font
                    if (fields.size == 3 && current != null) {
                        fields[1].toIntOrNull()?.let { map[Icon(current.family, fields[0])] = Entry(current, it.toDouble(), fields[2]) }
                    }
                }
            }
        }
        map
    }

    private val decoded = HashMap<Icon, IconGlyph?>()

    /** Null for an icon that was not generated. */
    fun glyph(icon: Icon): IconGlyph? = synchronized(decoded) {
        decoded.getOrPut(icon) {
            val entry = index[icon] ?: return@getOrPut null
            val path = GlyphOutline.decode(entry.outline) ?: return@getOrPut null
            IconGlyph(path, entry.font.unitsPerEm.toDouble(), entry.advance, entry.font.ascender.toDouble(), entry.font.descender.toDouble())
        }
    }

    val allIcons: List<Icon> get() = index.keys.toList()
}

/**
 * A glyph outline as generate-icons.py packs it, base64-encoded: a varint
 * contour count, each contour's point count as a varint; one on-curve bit
 * per point, least significant first; each point as zigzag varints dx, dy
 * from the previous one, in font units, y down from the ascender line.
 * Decoding replays TrueType's quadratic rules.
 */
internal object GlyphOutline {
    fun decode(base64: String): VectorPath? {
        val bytes = try {
            Base64.getDecoder().decode(base64)
        } catch (_: IllegalArgumentException) {
            return null
        }
        val reader = ByteReader(bytes)
        val contourCount = reader.varint() ?: return null
        val pointCounts = IntArray(contourCount) { reader.varint() ?: return null }
        val total = pointCounts.sum()
        val flags = reader.bytes((total + 7) / 8) ?: return null
        val points = ArrayList<Point>(total)
        var x = 0
        var y = 0
        repeat(total) {
            val dx = reader.zigzag() ?: return null
            val dy = reader.zigzag() ?: return null
            x += dx
            y += dy
            points += Point(x.toDouble(), y.toDouble())
        }
        if (!reader.isAtEnd) return null
        val elements = mutableListOf<PathElement>()
        var first = 0
        for (count in pointCounts) {
            val contour = (first until first + count).map { i -> points[i] to ((flags[i / 8].toInt() and (1 shl (i % 8))) != 0) }
            appendContour(contour, elements)
            first += count
        }
        return VectorPath(elements)
    }

    private fun appendContour(contour: List<Pair<Point, Boolean>>, elements: MutableList<PathElement>) {
        if (contour.isEmpty()) return
        val firstPoint = contour.first()
        val lastPoint = contour.last()
        val start: Point
        val rest: List<Pair<Point, Boolean>>
        when {
            firstPoint.second -> { start = firstPoint.first; rest = contour.drop(1) }
            lastPoint.second -> { start = lastPoint.first; rest = contour.dropLast(1) }
            else -> { start = midpoint(lastPoint.first, firstPoint.first); rest = contour }
        }
        elements += PathElement.Move(start)
        var control: Point? = null
        for ((point, onCurve) in rest) {
            val c = control
            if (onCurve) {
                if (c != null) {
                    elements += PathElement.QuadCurve(point, c)
                    control = null
                } else {
                    elements += PathElement.Line(point)
                }
            } else {
                if (c != null) elements += PathElement.QuadCurve(midpoint(c, point), c)
                control = point
            }
        }
        control?.let { elements += PathElement.QuadCurve(start, it) }
        elements += PathElement.Close
    }

    private fun midpoint(a: Point, b: Point) = Point((a.x + b.x) / 2, (a.y + b.y) / 2)

    private class ByteReader(private val bytes: ByteArray) {
        private var index = 0
        val isAtEnd get() = index == bytes.size

        fun varint(): Int? {
            var value = 0L
            var shift = 0
            while (index < bytes.size && shift < 63) {
                val byte = bytes[index].toInt() and 0xFF
                index++
                value = value or ((byte and 0x7F).toLong() shl shift)
                if (byte and 0x80 == 0) return value.toInt()
                shift += 7
            }
            return null
        }

        fun zigzag(): Int? {
            val raw = varint() ?: return null
            return if (raw and 1 == 0) raw shr 1 else -((raw + 1) shr 1)
        }

        fun bytes(count: Int): ByteArray? {
            if (index + count > bytes.size) return null
            return bytes.copyOfRange(index, index + count).also { index += count }
        }
    }
}
